import{_ as r,C as a,o,c as n,E as s,a2 as i}from"./chunks/framework.Cm6XCzck.js";const y=JSON.parse(`{"title":"A Green Check Describes the Present: What CrewAI's Failure-Telemetry Fix Reveals About Agent Delivery Boundaries","description":"","frontmatter":{"title":"A Green Check Describes the Present: What CrewAI's Failure-Telemetry Fix Reveals About Agent Delivery Boundaries","date":"2026-08-26","column":"digital-employee","category":"daily","article_type":"engineering-insight","edition":"research-center","research_question":"How can technical failure, current delivery state, formal acceptance, and historical evidence remain simultaneously visible without one layer impersonating another?","summary":"Starting from CrewAI's task-failure telemetry repair and a CodeFlowMu report-projection defect, this study argues that technical outcomes, delivery evidence, current state, formal acceptance, and history must remain distinct records.","sources":"Public primary sources and the bounded scope of access-controlled first-party evidence are listed in the article.","project_relevance":"case-evidence","item_id":"EBR-20260826-03","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-26-agent-failure-and-delivery-boundary-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/digital-employee/2026-08-26-agent-failure-and-delivery-boundary.md","filePath":"en/digital-employee/2026-08-26-agent-failure-and-delivery-boundary.md","lastUpdated":1787803877000}`),l={name:"en/digital-employee/2026-08-26-agent-failure-and-delivery-boundary.md"};function c(d,e,u,h,p,m){const t=a("ArticleCover");return o(),n("div",null,[s(t,{image:"/assets/covers/daily-2026-08-26-agent-failure-and-delivery-boundary-cover.png",kicker:"Digital Employee · Engineering Research",title:"A Green Check Describes the Present: What CrewAI's Failure-Telemetry Fix Reveals About Agent Delivery Boundaries",summary:"A later success must not rewrite an earlier failure, and a current delivery view must not erase history. Execution facts, evidence, and acceptance need separate ledgers.",version:"EBR-20260826-03",status:"Engineering Research · 2026-08-26",languageHref:"/zh/digital-employee/2026-08-26-agent-failure-and-delivery-boundary",languageLabel:"中文"}),e[0]||(e[0]=i('<h1 id="a-green-check-describes-the-present-what-crewai-s-failure-telemetry-fix-reveals-about-agent-delivery-boundaries" tabindex="-1">A Green Check Describes the Present: What CrewAI&#39;s Failure-Telemetry Fix Reveals About Agent Delivery Boundaries <a class="header-anchor" href="#a-green-check-describes-the-present-what-crewai-s-failure-telemetry-fix-reveals-about-agent-delivery-boundaries" aria-label="Permalink to &quot;A Green Check Describes the Present: What CrewAI&#39;s Failure-Telemetry Fix Reveals About Agent Delivery Boundaries&quot;">​</a></h1><p>If an agent task ends with a green “completed” state, does that prove nothing failed along the way?</p><p>No.</p><p>If one tool call fails, does that prove the business task failed?</p><p>Also no.</p><p><strong>CodeFlowMu is a locally run multi-agent collaboration system that uses tasks, roles, gates, reports, and approvals to organize agent work into an execution chain that can be traced, recovered, and verified.</strong></p><p>In a system like this, the dangerous failure mode is not simply that something goes wrong. It is that several different kinds of truth are flattened into one status: a technical error becomes a business rejection; a later retry overwrites the earlier failure; a current report hides a returned or superseded one; a green check gradually comes to mean “nothing bad ever happened.”</p><p>This article is not about making the interface greener. It is about allowing different facts to remain true at the same time.</p><h2 id="bottom-line-three-boundaries-must-not-collapse" tabindex="-1">Bottom line: three boundaries must not collapse <a class="header-anchor" href="#bottom-line-three-boundaries-must-not-collapse" aria-label="Permalink to &quot;Bottom line: three boundaries must not collapse&quot;">​</a></h2><p>An auditable agent runtime needs to preserve at least three inequalities:</p><ul><li><strong>technical failure ≠ delivery rejection</strong>: a technical failure is first an execution fact; it does not automatically mean the business delivery was rejected;</li><li><strong>successful action ≠ accepted delivery</strong>: a zero exit code, passing test, or generated report creates evidence, not formal acceptance;</li><li><strong>current state ≠ history</strong>: the current state may change, but earlier failures, returns, replacements, and resolved records must not disappear with it.</li></ul><p>Once those distinctions are compressed into one <code>status</code>, a particularly difficult class of bug appears: the UI looks coherent while the audit chain is already false.</p><h2 id="a-concrete-crewai-failure-the-task-failed-but-telemetry-said-ok" tabindex="-1">A concrete CrewAI failure: the task failed, but telemetry said OK <a class="header-anchor" href="#a-concrete-crewai-failure-the-task-failed-but-telemetry-said-ok" aria-label="Permalink to &quot;A concrete CrewAI failure: the task failed, but telemetry said OK&quot;">​</a></h2><p>CrewAI merged <a href="https://github.com/crewAIInc/crewAI/pull/7073" target="_blank" rel="noreferrer">PR #7073</a> in August 2026 to repair a direct false-green telemetry path. A task-failure event had been routed through the normal task-ended path, where <code>close_span()</code> marked the span <code>StatusCode.OK</code>. A separate crew-less failure path could also remove a span without correctly ending and exporting it.</p><p>The repair routes task failure through an error path, records <code>StatusCode.ERROR</code>, and retains a constrained <code>error_type</code>. The PR deliberately records the exception type rather than the exception message, reducing the chance that prompts, paths, or credentials are copied into telemetry.</p><p>The important lesson is broader than CrewAI:</p><blockquote><p><strong>A technical failure that occurred must remain recorded as a failure. A later recovery must not rewrite the earlier event as success.</strong></p></blockquote><p>But that principle covers only the execution layer. If a runtime then converts every tool failure directly into “business task failed,” it creates a different category error. Timeouts, environment faults, authority rejections, cancellation, or lost processes may require retry, takeover, or reauthorization. They are execution facts first. Their effect on delivery has to be decided by task evidence and acceptance rules later.</p><h2 id="codeflowmu-exposed-the-other-half-a-correct-present-must-not-displace-history" tabindex="-1">CodeFlowMu exposed the other half: a correct present must not displace history <a class="header-anchor" href="#codeflowmu-exposed-the-other-half-a-correct-present-must-not-displace-history" aria-label="Permalink to &quot;CodeFlowMu exposed the other half: a correct present must not displace history&quot;">​</a></h2><p>The public CodeFlowMu A3 evidence is not a tool-error taxonomy. It concerns the <strong>projection of reports and ISSUE records into a current view</strong>.</p><p>The first record-precedence run passed only <strong>55 / 57</strong> checks. Two superseded or invalid final records could still be selected by the rule that chose the current main report. The data had not disappeared; the projection had put historical records in the wrong place.</p><p>After the repair, the same collection reached <strong>57 / 57</strong>. A follow-up semantic route regression passed <strong>14 / 14</strong>, and the Reports / Issues / Mobile / Web Panel integration set passed <strong>221 / 221</strong>. These figures verify the named paths only; they are not evidence that every future failure will propagate losslessly through the entire system.</p><p>A controlled runtime snapshot recorded the following projection:</p><table tabindex="0"><thead><tr><th>Projection</th><th style="text-align:right;">Observed count</th><th>What it means</th></tr></thead><tbody><tr><td>Current root report</td><td style="text-align:right;">1</td><td>the report currently selected for the root task</td></tr><tr><td>Current subtask reports</td><td style="text-align:right;">4</td><td>currently visible reports in the task chain</td></tr><tr><td>Historical reports</td><td style="text-align:right;">12</td><td>retained and traceable, but not presented as current conclusions</td></tr><tr><td>Resolved ISSUE records</td><td style="text-align:right;">6</td><td>closed historical problems whose records remain present</td></tr><tr><td>Open ISSUE records</td><td style="text-align:right;">1</td><td>one issue still requiring current attention</td></tr></tbody></table><p>The evidence supports a narrow but important claim:</p><blockquote><p><strong>A correct current view must not be manufactured by deleting, hiding, or misclassifying history.</strong></p></blockquote><p>A green check can describe the current projection. It cannot truthfully mean “there was never a failure,” “nothing was returned,” or “no record was ever superseded.”</p><h2 id="why-these-two-cases-are-really-about-the-same-boundary" tabindex="-1">Why these two cases are really about the same boundary <a class="header-anchor" href="#why-these-two-cases-are-really-about-the-same-boundary" aria-label="Permalink to &quot;Why these two cases are really about the same boundary&quot;">​</a></h2><p>CrewAI #7073 and CodeFlowMu A3 operate at different layers: one concerns telemetry, the other task/report projection. Neither implementation validates the other. But both expose the same data-governance risk: <strong>a later state overwrites the truth of an earlier event.</strong></p><p>A more robust agent system should keep at least four kinds of facts separate:</p><table tabindex="0"><thead><tr><th>Layer</th><th>Question</th><th>Typical records</th></tr></thead><tbody><tr><td>Execution fact</td><td>What happened to this tool call or job?</td><td>completed / failed / cancelled / timeout</td></tr><tr><td>Delivery evidence</td><td>What inspectable material did the work produce?</td><td>REPORT, test result, change summary, artifact</td></tr><tr><td>Formal acceptance</td><td>Did an authorized role accept that evidence?</td><td>accepted / returned / rejected / pending</td></tr><tr><td>Current projection and history</td><td>What should be shown now, and what happened before?</td><td>current / superseded / historical / resolved / open</td></tr></tbody></table><p>The layers may reference one another. They must not overwrite one another.</p><p>For example:</p><p><code>tool failed → retry succeeded → report submitted → review accepted</code></p><p>That chain can legitimately end in a business-level “completed” state, while the initial technical failure remains part of the record. The reverse is also true: <code>tool succeeded</code> describes one execution result. Without delivery evidence or formal acceptance, it cannot promote itself into “task delivered.”</p><h2 id="crewai-7079-adds-a-neighboring-question-whose-action-was-this" tabindex="-1">CrewAI #7079 adds a neighboring question: whose action was this? <a class="header-anchor" href="#crewai-7079-adds-a-neighboring-question-whose-action-was-this" aria-label="Permalink to &quot;CrewAI #7079 adds a neighboring question: whose action was this?&quot;">​</a></h2><p>Another merged CrewAI repair, <a href="https://github.com/crewAIInc/crewAI/pull/7079" target="_blank" rel="noreferrer">PR #7079</a>, separates framework-internal Flows from execution boundaries actually owned by the caller. Internal routing and memory-recall machinery no longer automatically receives the same interception treatment as a user-requested business action, while standalone <code>Agent.kickoff()</code> remains observable and blockable when it owns the execution boundary.</p><p>This is not a direct implementation analogue for CodeFlowMu A3. It adds a prerequisite to the same engineering problem: before classifying an event as success or failure, the runtime must know <strong>whether the event belongs to the user&#39;s business execution or to internal framework machinery</strong>. If provenance is wrong, failure metrics, delivery conclusions, and governance decisions will all inherit the error.</p><h2 id="what-should-a-green-check-actually-require" tabindex="-1">What should a green check actually require? <a class="header-anchor" href="#what-should-a-green-check-actually-require" aria-label="Permalink to &quot;What should a green check actually require?&quot;">​</a></h2><p>If “completed” is treated as the final projection shown on a task page, it should satisfy at least these constraints:</p><ol><li><strong>failure is not rewritten</strong>: later recovery may resolve a failure, but it must not erase the original technical event;</li><li><strong>execution does not impersonate acceptance</strong>: a zero exit code, passing tests, or a generated file cannot sign off a business delivery by itself;</li><li><strong>the present does not consume history</strong>: superseded, returned, invalidated, and resolved records remain traceable;</li><li><strong>the projection has provenance</strong>: the system can explain why this report or ISSUE count is current by referring back to a ledger and lineage rule;</li><li><strong>internal machinery does not impersonate business action</strong>: framework-internal routing, memory, and Flow activity remain distinguishable from the execution the caller actually requested.</li></ol><p>Under those conditions, “completed” is not a color. It is a current conclusion projected from multiple preserved facts.</p><h2 id="conclusion-a-trustworthy-system-does-not-eliminate-red-it-prevents-green-from-rewriting-it" tabindex="-1">Conclusion: a trustworthy system does not eliminate red; it prevents green from rewriting it <a class="header-anchor" href="#conclusion-a-trustworthy-system-does-not-eliminate-red-it-prevents-green-from-rewriting-it" aria-label="Permalink to &quot;Conclusion: a trustworthy system does not eliminate red; it prevents green from rewriting it&quot;">​</a></h2><p>Failures are normal in agent systems. Networks break. Commands fail. Reports are returned. Conclusions are superseded. Historical ISSUEs are resolved while new ones remain open.</p><p>The dangerous shortcut is to flatten all of those facts into one binary success/failure label.</p><p>A stronger runtime does the opposite: <strong>the execution layer preserves failure truthfully, the delivery layer preserves evidence, the acceptance layer makes the business decision, the projection layer says what should be shown now, and history remains intact underneath.</strong></p><p>The most accurate meaning of a green check is therefore not “nothing went wrong.” It is:</p><blockquote><p><strong>Given the preserved history and the evidence currently in force, the system has enough grounds to project this task as complete now.</strong></p></blockquote><p>That is the boundary a “completed” state should carry in a digital-employee runtime.</p><h2 id="public-evidence-what-a3-actually-proves" tabindex="-1">Public evidence: what A3 actually proves <a class="header-anchor" href="#public-evidence-what-a3-actually-proves" aria-label="Permalink to &quot;Public evidence: what A3 actually proves&quot;">​</a></h2><p>The first A3 record-precedence run was <strong>55 / 57</strong> because superseded or invalid final records could still win the current main-report selection. After repair it became <strong>57 / 57</strong>; the follow-up semantic route check was <strong>14 / 14</strong>, and the Reports / Issues / Mobile / Web Panel integration set was <strong>221 / 221</strong>.</p><p>The controlled snapshot contained one current root report, four current subtask reports, twelve historical reports, six resolved ISSUE records, and one open ISSUE. This evidence supports two claims: a green current view must not erase history, and a record-precedence defect was observed before the passing repair. It <strong>does not prove</strong> that every technical failure propagates through REPORT, REVIEW, and every UI surface, and it is not a global failure-rate measurement.</p><ul><li><a href="/joinwell52/evidence/execution-boundary-20260826/v2/case-a3-projection-precedence-trace.csv">A3 report-projection trace (CSV)</a></li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/docs/public/evidence/execution-boundary-20260826/v2/transcript-a3.md" target="_blank" rel="noreferrer">A3 sanitized test and runtime transcript (GitHub)</a></li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/docs/public/evidence/execution-boundary-20260826/v2/claim-evidence-map.csv" target="_blank" rel="noreferrer">Claim-to-evidence map (GitHub)</a></li></ul><h3 id="sources-and-evidence-boundary" tabindex="-1">Sources and evidence boundary <a class="header-anchor" href="#sources-and-evidence-boundary" aria-label="Permalink to &quot;Sources and evidence boundary&quot;">​</a></h3><ul><li><a href="https://github.com/crewAIInc/crewAI/pull/7073" target="_blank" rel="noreferrer">CrewAI PR #7073</a>: <code>fix(events): record task failures as failures, not as successes</code>, merged 2026-08-25. This article uses only its public implementation facts about routing task failures through ERROR semantics and retaining a constrained <code>error_type</code>.</li><li><a href="https://github.com/crewAIInc/crewAI/pull/7079" target="_blank" rel="noreferrer">CrewAI PR #7079</a>: <code>fix: skip interception hooks on crewai-internal flows</code>, merged 2026-08-25. It is used only as a neighboring example of separating internal machinery from caller-owned execution boundaries.</li><li>The scope, runtime snapshot, and non-generalization limits for the CodeFlowMu A3 evidence are documented in the <a href="/joinwell52/zh/digital-employee/2026-08-26-execution-boundary-evidence-data">public redacted four-case evidence note</a>. Raw logs, task bodies, and local machine paths are not public.</li></ul>',55))])}const f=r(l,[["render",c]]);export{y as __pageData,f as default};
